using System;
using SilentOrders.Core;

namespace SilentOrders.Rendering
{
    public static class SniperSprites
    {
        public static readonly PawnSprites.Sprite[] Atlas = new PawnSprites.Sprite[2]
        {
            new PawnSprites.Sprite(
                96,
                24,
                ""
            ),
            new PawnSprites.Sprite(
                96,
                23,
                ""
            ),
        };
        public static readonly float[] BarrelY = new float[2] { -0.0188679f, -0.0776699f };

        public static int Height(int variant, int width)
        {
            PawnSprites.Sprite sprite = Atlas[(variant == 5) ? 1 : 0];
            return (int)Math.Round((float)(Math.Abs(width) * sprite.H) / (float)sprite.W);
        }

        public static void Draw(
            PixelCanvas canvas,
            int variant,
            float cx,
            float cy,
            int width,
            int height,
            float angle = 0f
        )
        {
            Rubezh.Graphics.Sniper(canvas, variant, cx, cy, width, height, angle);
        }
    }
}
